// tools/heatmap/index.tsx — App orchestrator for the Heatmap tool. This
// file is the esbuild entry point (bundles to tools/heatmap/index.js) and
// only holds state wiring — chart rendering, step panels, sidebar controls,
// detail view, reports, and pure helpers all live in sibling modules under
// tools/heatmap/.

import {
  ChartDataTable,
  DataPreview,
  DetectedSeparatorBadge,
  MethodsButton,
  PlotToolShell,
  softwareSentence,
  usePlotToolState,
} from "../_shell";
import type { ChartDataTableRow } from "../_shell";
import { getLang } from "../_core/i18n";
import "./i18n";
import { tt, useT } from "./i18n";
import {
  normalizeMatrix,
  sortedFiniteValues,
  detectRangeSkew,
  fullRange,
  rangePresets,
} from "./helpers";
import type {
  AxisClusterMeta,
  BrushBox,
  CellBorderState,
  ClusterMode,
  ClusterResult,
  DistanceMetric,
  HeatmapSelection,
  LinkageMethod,
  MatrixExportRef,
  Normalization,
} from "./helpers";
import { HeatmapChart } from "./chart";
import { UploadStep } from "./steps";
import { PlotControls, SkewAlert } from "./controls";
import { DetailView, DetailPreviewCard } from "./plot-area";

import { DIVERGING_PALETTES } from "../_core/color";
import { seededRandom } from "../_core/numeric";
import { autoDetectSep, fixDecimalCommas, parseWideMatrix } from "../_core/csv";
import { hclust, kmeans, pairwiseDistance } from "../_core/stats/cluster";
const { useState, useReducer, useMemo, useCallback, useRef } = React;

// Per-mode ceilings on the number of observations (rows for row-clustering,
// columns for column-clustering) we will cluster on the main thread — there
// is no Web Worker, so the whole compute blocks the tab. The two modes scale
// very differently, so a single shared cap is wrong:
//
//   • Hierarchical: `pairwiseDistance` builds an N×N matrix and `hclust` is
//     naive-agglomerative O(N³). Measured (V8, ~12 features): N=2,000 ≈ 3.5s,
//     N=3,000 ≈ 11s, N=5,000 ≈ 47s — and far worse (minutes) once the N×N
//     distance matrix thrashes GC. 2,000 keeps the worst case to a few seconds.
//   • K-means: near-linear in N and O(N) memory. Measured: N=5,000 ≈ 3s, so
//     ~10,000 (≈6s) is a comfortable ceiling.
//
// Above the relevant cap we fall back to the unclustered (file) order and
// surface a note. Both sit well above any realistic heatmap (the bundled demo
// is 500×6); users who need to cluster more rows should prefer k-means.
const HCLUST_MAX_OBS = 2000;
const KMEANS_MAX_OBS = 10000;
const clusterCapFor = (mode: ClusterMode): number =>
  mode === "hierarchical" ? HCLUST_MAX_OBS : mode === "kmeans" ? KMEANS_MAX_OBS : Infinity;

// Cap the accessible data-table size — a `<table>` of a multi-thousand-square
// matrix would balloon the DOM. Render rows up to this cell budget and note
// the truncation; the chart itself is unaffected.
const TABLE_MAX_CELLS = 20000;

const VIS_INIT_HEATMAP = {
  palette: "viridis",
  invertPalette: false,
  vmin: 0,
  vmax: 1,
  plotTitle: "",
  plotSubtitle: "",
  colAxisLabel: "",
  rowAxisLabel: "",
  showRowLabels: false,
  showColLabels: true,
  // Whether each hierarchical-clustering dendrogram renders on the plot
  // (independent per axis). Dendrograms are essential for defining /
  // selecting clusters (click a branch to open the zoomed selection), but
  // once the order + cluster structure is locked in, users often want a
  // cleaner final figure. Turning one off hides that axis's tree lines +
  // hit-rects and reclaims the reserved margin; leaf ORDER is preserved
  // (that's what the user committed to); drag-select on the heatmap still
  // opens detail views. Applies to both the main and zoomed plots.
  showRowDendrogram: true,
  showColDendrogram: true,
  // Distribution of the displayed values drawn beside the colourbar (and
  // exported with it), so a reader sees where the data sit on the scale.
  showLegendHistogram: true,
};

// ── Embedded example dataset (500 genes × 6 samples) ────────────────────────
// Generated deterministically from a seeded RNG so the example is reproducible
// across reloads. Five latent response patterns with 100 genes each — stress
// induced (strong / moderate / mild), stress repressed, non-responsive —
// arranged so clustering (hierarchical or k=5 k-means) recovers meaningful
// structure and the zoom/detail view has a non-trivial matrix to slice.
const EXAMPLE_CSV = (() => {
  const rand = seededRandom(42);
  const header = "gene,Control1,Control2,Control3,Stress1,Stress2,Stress3";
  // Each pattern: [ctrlLo, ctrlHi] and [stressLo, stressHi] sampling ranges
  // for the per-gene base level, plus a per-replicate noise amplitude.
  const patterns = [
    { label: "up-strong", ctrl: [0.6, 1.4], stress: [3.8, 5.6], noise: 0.35 },
    { label: "up-moderate", ctrl: [0.8, 1.6], stress: [2.2, 3.4], noise: 0.3 },
    { label: "up-mild", ctrl: [0.7, 1.5], stress: [1.8, 2.6], noise: 0.25 },
    { label: "down", ctrl: [3.2, 4.8], stress: [0.6, 1.4], noise: 0.35 },
    { label: "flat", ctrl: [0.8, 2.4], stress: [0.8, 2.4], noise: 0.3 },
  ];
  const perPattern = 100;
  const lines = [header];
  let geneIdx = 0;
  for (const p of patterns) {
    for (let i = 0; i < perPattern; i++) {
      geneIdx++;
      const geneName = `gene${String(geneIdx).padStart(3, "0")}`;
      const ctrlBase = p.ctrl[0] + rand() * (p.ctrl[1] - p.ctrl[0]);
      const stressBase = p.stress[0] + rand() * (p.stress[1] - p.stress[0]);
      const cols: string[] = [];
      for (let j = 0; j < 3; j++) cols.push((ctrlBase + (rand() - 0.5) * 2 * p.noise).toFixed(2));
      for (let j = 0; j < 3; j++) cols.push((stressBase + (rand() - 0.5) * 2 * p.noise).toFixed(2));
      lines.push([geneName, ...cols].join(","));
    }
  }
  // Three "saturated well" spikes, so the sample demonstrates the outlier-skew
  // alert: they stretch the raw colour scale to ~52 while every other value
  // sits below ~6. Overwritten after generation so the seeded stream (and
  // every other cell) is unchanged.
  const spikes: [number, number, string][] = [
    [42, 5, "48.70"], // gene042, Stress2
    [217, 1, "36.20"], // gene217, Control1
    [388, 6, "52.40"], // gene388, Stress3
  ];
  for (const [gene, col, value] of spikes) {
    const cells = lines[gene].split(",");
    cells[col] = value;
    lines[gene] = cells.join(",");
  }
  return lines.join("\n");
})();

// ── App ──────────────────────────────────────────────────────────────────────

export function App() {
  const tr = useT();
  const shell = usePlotToolState("heatmap", VIS_INIT_HEATMAP);
  const {
    step,
    setStep,
    fileName,
    setFileName,
    setParseError,
    sepOverride,
    setSepOverride,
    setCommaFixed,
    setCommaFixCount,
    setInjectionWarning,
    vis,
    updVis,
  } = shell;

  const [rawMatrix, setRawMatrix] = useState<{
    rowLabels: string[];
    colLabels: string[];
    matrix: number[][];
  }>({ rowLabels: [], colLabels: [], matrix: [] });
  const [warnings, setWarnings] = useState({ nonNumeric: 0 });
  // Separator the auto-detector resolved on the most recent parse. Surfaced
  // inline on the Import check step's file-info line.
  const [detectedSep, setDetectedSep] = useState<string>("");

  const [normalization, setNormalization] = useState<Normalization>("none");
  const [rowMode, setRowMode] = useState<ClusterMode>("hierarchical");
  const [colMode, setColMode] = useState<ClusterMode>("hierarchical");
  const [rowK, setRowK] = useState(3);
  const [colK, setColK] = useState(3);
  const [kmeansSeed, setKmeansSeed] = useState(1);
  const [distanceMetric, setDistanceMetric] = useState<DistanceMetric>("euclidean");
  const [linkageMethod, setLinkageMethod] = useState<LinkageMethod>("average");

  const cellBorderInit: CellBorderState = { on: false, color: "#ffffff", width: 0.5 };
  const [cellBorder, updCellBorder] = useReducer(
    (s: CellBorderState, a: Partial<CellBorderState> | { _reset: true }): CellBorderState =>
      "_reset" in a && a._reset
        ? { ...cellBorderInit }
        : { ...s, ...(a as Partial<CellBorderState>) },
    cellBorderInit
  );

  const chartRef = useRef<SVGSVGElement | null>(null);
  const detailChartRef = useRef<SVGSVGElement | null>(null);
  const matrixRef = useRef<MatrixExportRef | null>(null);

  // Selection state: which rows / columns are highlighted for the detail view.
  // `null` on an axis means "all rows/cols". Indices are into the ORIGINAL
  // rawMatrix, not into rowOrder/colOrder — so clustering changes don't
  // invalidate them.
  const [selection, setSelection] = useState<HeatmapSelection>({
    rows: null,
    cols: null,
    clusterId: null,
    clusterAxis: null,
  });

  const selectBox = useCallback((rows: number[] | null, cols: number[] | null) => {
    setSelection({
      rows: rows && rows.length ? rows : null,
      cols: cols && cols.length ? cols : null,
      clusterId: null,
      clusterAxis: null,
    });
  }, []);
  // Axis-scoped selection (dendrogram branch / cluster strip click) REPLACES
  // any prior selection rather than layering onto it — otherwise clicking a
  // column subtree after a row brush would intersect the two, which doesn't
  // match the user's mental model of "show me this subtree".
  const selectAxis = useCallback(
    (axis: "row" | "col", indices: number[] | null, meta: AxisClusterMeta | null | undefined) => {
      const valid = indices && indices.length ? indices : null;
      setSelection({
        rows: axis === "row" ? valid : null,
        cols: axis === "col" ? valid : null,
        clusterId: meta && meta.clusterId != null ? meta.clusterId : null,
        clusterAxis: meta && meta.clusterId != null ? axis : null,
      });
    },
    []
  );
  const clearSelection = useCallback(
    () => setSelection({ rows: null, cols: null, clusterId: null, clusterAxis: null }),
    []
  );

  // Normalised matrix (memoised on the raw matrix + mode).
  const normalized = useMemo(
    () => normalizeMatrix(rawMatrix.matrix, normalization),
    [rawMatrix, normalization]
  );

  // Clustering — expensive; only recompute when relevant inputs change.
  const rowCluster = useMemo<ClusterResult | null>(() => {
    // Too many rows to cluster on the main thread — fall back to file order.
    if (normalized.length > clusterCapFor(rowMode)) return null;
    if (rowMode === "hierarchical") {
      if (normalized.length < 2) return null;
      const D = pairwiseDistance(normalized, distanceMetric);
      const h = hclust(D, linkageMethod);
      // hclust on >= 2 observations always yields a root; the guard keeps
      // the type honest (HClustResult.tree is `… | null`) without a cast.
      if (!h.tree) return null;
      return { mode: "hierarchical", tree: h.tree, order: h.order };
    }
    if (rowMode === "kmeans") {
      if (normalized.length < 2) return null;
      const k = Math.max(2, Math.min(rowK, normalized.length));
      const res = kmeans(normalized, k, { seed: kmeansSeed });
      return { mode: "kmeans", clusters: res.clusters, order: res.order, k };
    }
    return null;
  }, [rowMode, normalized, distanceMetric, linkageMethod, rowK, kmeansSeed]);

  const colCluster = useMemo<ClusterResult | null>(() => {
    if (normalized.length < 1 || normalized[0].length < 2) return null;
    // Too many columns to cluster on the main thread — fall back to file order.
    if (normalized[0].length > clusterCapFor(colMode)) return null;
    // Transpose once — both hierarchical and k-means need column-as-observation.
    const nRows = normalized.length;
    const nCols = normalized[0].length;
    const T = Array.from({ length: nCols }, (_, c) => {
      const row = new Array(nRows);
      for (let r = 0; r < nRows; r++) row[r] = normalized[r][c];
      return row;
    });
    if (colMode === "hierarchical") {
      const D = pairwiseDistance(T, distanceMetric);
      const h = hclust(D, linkageMethod);
      // hclust on >= 2 observations always yields a root; the guard keeps
      // the type honest (HClustResult.tree is `… | null`) without a cast.
      if (!h.tree) return null;
      return { mode: "hierarchical", tree: h.tree, order: h.order };
    }
    if (colMode === "kmeans") {
      const k = Math.max(2, Math.min(colK, nCols));
      const res = kmeans(T, k, { seed: kmeansSeed });
      return { mode: "kmeans", clusters: res.clusters, order: res.order, k };
    }
    return null;
  }, [colMode, normalized, distanceMetric, linkageMethod, colK, kmeansSeed]);

  const rowOrder = useMemo(() => {
    if (rowCluster) return rowCluster.order;
    return rawMatrix.rowLabels.map((_, i) => i);
  }, [rowCluster, rawMatrix.rowLabels]);

  const colOrder = useMemo(() => {
    if (colCluster) return colCluster.order;
    return rawMatrix.colLabels.map((_, i) => i);
  }, [colCluster, rawMatrix.colLabels]);

  // Detail slice — honours current rowOrder/colOrder for visual continuity
  // with the main plot, but filters to the selection (null = all on axis).
  const detailRowOrder = useMemo(() => {
    if (!selection.rows) return rowOrder;
    const keep = new Set(selection.rows);
    return rowOrder.filter((i) => keep.has(i));
  }, [rowOrder, selection.rows]);
  const detailColOrder = useMemo(() => {
    if (!selection.cols) return colOrder;
    const keep = new Set(selection.cols);
    return colOrder.filter((i) => keep.has(i));
  }, [colOrder, selection.cols]);
  const hasSelection = selection.rows !== null || selection.cols !== null;

  // A brush on the MAIN chart sends display-space (ri, ci) ranges; convert to
  // original indices via rowOrder/colOrder before storing in selection.
  const onBrushEnd = useCallback(
    ({ riMin, riMax, ciMin, ciMax }: BrushBox) => {
      const rows: number[] = [];
      for (let ri = riMin; ri <= riMax; ri++) if (rowOrder[ri] != null) rows.push(rowOrder[ri]);
      const cols: number[] = [];
      for (let ci = ciMin; ci <= ciMax; ci++) if (colOrder[ci] != null) cols.push(colOrder[ci]);
      selectBox(rows, cols);
    },
    [rowOrder, colOrder, selectBox]
  );

  // Any change in cluster structure invalidates the current selection —
  // the indices still point at real rows/cols but the user's mental map is
  // now wrong. Clear rather than silently mis-highlight.
  React.useEffect(() => {
    clearSelection();
  }, [
    rowMode,
    colMode,
    rowK,
    colK,
    kmeansSeed,
    distanceMetric,
    linkageMethod,
    normalization,
    clearSelection,
  ]);

  // Keep the CSV-export ref in sync with what's currently plotted. Lives in
  // an effect (not the render body) so Strict Mode's double-invoke can't
  // leave the ref half-updated between the two renders.
  React.useEffect(() => {
    matrixRef.current = {
      rowLabels: rawMatrix.rowLabels,
      colLabels: rawMatrix.colLabels,
      matrix: normalized,
      rowOrder,
      colOrder,
      rowClusterIds: rowCluster && rowCluster.mode === "kmeans" ? rowCluster.clusters : null,
      colClusterIds: colCluster && colCluster.mode === "kmeans" ? colCluster.clusters : null,
    };
  }, [rawMatrix, normalized, rowOrder, colOrder, rowCluster, colCluster]);

  const rangeIsDiverging = DIVERGING_PALETTES.has(vis.palette) || normalization.startsWith("z");
  // Sorted once per data change; presets, the skew alert and the sidebar
  // histogram all read from it, so dragging Min / Max stays cheap.
  const sortedValues = useMemo(() => sortedFiniteValues(normalized), [normalized]);
  const presets = useMemo(
    () => rangePresets(sortedValues, rangeIsDiverging),
    [sortedValues, rangeIsDiverging]
  );
  const setRange = useCallback(
    (lo: number, hi: number) => updVis({ vmin: lo, vmax: hi }),
    [updVis]
  );
  const autoVRange = useCallback(() => {
    setRange(presets.full[0], presets.full[1]);
  }, [presets, setRange]);

  // Outlier-skew alert: a few extreme cells stretching the colour scale.
  const skew = useMemo(
    () => detectRangeSkew(sortedValues, vis.vmin, vis.vmax, rangeIsDiverging),
    [sortedValues, vis.vmin, vis.vmax, rangeIsDiverging]
  );
  const applyRobustRange = useCallback(() => {
    if (skew) setRange(skew.suggestedMin, skew.suggestedMax);
  }, [skew, setRange]);

  // The colorbar range must follow the normalization mode: switching
  // none → z-score (values ≈ ±3) or → log2 shifts the value scale
  // entirely, so a vmin/vmax left from the previous scale renders the
  // heatmap as a saturated, near-uniform block. Re-range on a genuine
  // normalization change. The ref-compare keeps this from firing when
  // the autoVRange closure is merely recreated for a palette/data change,
  // and skips the initial mount — doParse already ranges the raw data.
  const prevNormRef = useRef(normalization);
  React.useEffect(() => {
    if (prevNormRef.current !== normalization) {
      prevNormRef.current = normalization;
      autoVRange();
    }
  }, [normalization, autoVRange]);

  // Crossing between a diverging and a sequential palette also re-ranges
  // the colorbar: a diverging palette wants a symmetric vmin/vmax centred
  // on 0, a sequential one wants the data's own [min, max]. Keyed on the
  // palette's diverging-ness (not the palette itself), so a sequential →
  // sequential swap such as viridis → plasma leaves a manual range alone.
  const paletteIsDiverging = DIVERGING_PALETTES.has(vis.palette);
  const prevPaletteDivergingRef = useRef(paletteIsDiverging);
  React.useEffect(() => {
    if (prevPaletteDivergingRef.current !== paletteIsDiverging) {
      prevPaletteDivergingRef.current = paletteIsDiverging;
      autoVRange();
    }
  }, [paletteIsDiverging, autoVRange]);

  const canNavigate = useCallback(
    (target: string) => {
      if (target === "upload") return true;
      if (target === "configure") return rawMatrix.rowLabels.length > 0;
      if (target === "plot") return rawMatrix.rowLabels.length > 0;
      return false;
    },
    [rawMatrix]
  );

  const doParse = useCallback(
    (text: string, sep: string) => {
      // Resolve "auto" (sep === "") before fixDecimalCommas so European
      // semicolon-delimited matrices still get their decimal commas
      // fixed — `fixDecimalCommas` short-circuits on sep === "". Same
      // pattern as boxplot/app.tsx.
      const resolved = autoDetectSep(text, sep);
      const effectiveSep = typeof resolved === "string" ? resolved : "";
      setDetectedSep(effectiveSep);
      const dc = fixDecimalCommas(text, effectiveSep);
      setCommaFixed(dc.commaFixed);
      setCommaFixCount(dc.count);
      const parsed = parseWideMatrix(dc.text, effectiveSep);
      setInjectionWarning(parsed.injectionWarnings);
      if (!parsed.rowLabels.length || !parsed.colLabels.length) {
        setParseError(tt("heatmap.err.matrix"));
        return;
      }
      setParseError(null);
      setRawMatrix({
        rowLabels: parsed.rowLabels,
        colLabels: parsed.colLabels,
        matrix: parsed.matrix,
      });
      setWarnings(parsed.warnings);

      // Auto-range the colour scale from the raw data on first load
      // (sequential: normalisation starts at "none").
      const [lo, hi] = fullRange(sortedFiniteValues(parsed.matrix), false);
      updVis({ vmin: lo, vmax: hi });
      setStep("configure");
    },
    [setCommaFixed, setCommaFixCount, setInjectionWarning, setParseError, setStep, updVis]
  );

  const handleFileLoad = useCallback(
    (text: string, name: string) => {
      setFileName(name);
      doParse(text, sepOverride);
    },
    [sepOverride, doParse, setFileName]
  );

  // Paste-data path. UploadPanel hands raw text + a synthetic filename;
  // size is gated in the panel against FILE_LIMIT_BYTES. Force
  // sepOverride="" so auto-detect kicks in for Excel/Sheets paste.
  const handleTextPaste = useCallback(
    (text: string, name: string) => {
      setFileName(name);
      setSepOverride("");
      doParse(text, "");
    },
    [doParse, setFileName, setSepOverride]
  );

  const loadExample = useCallback(() => {
    // Leave sepOverride empty so the Override disclosure stays closed on
    // back-nav; autoDetectSep resolves "," from the bundled CSV.
    setSepOverride("");
    setFileName("stress_response_genes.csv");
    doParse(EXAMPLE_CSV, "");
  }, [doParse, setFileName, setSepOverride]);

  const resetAll = () => {
    setStep("upload");
    setFileName("");
    setRawMatrix({ rowLabels: [], colLabels: [], matrix: [] });
    setWarnings({ nonNumeric: 0 });
    setNormalization("none");
    setRowMode("hierarchical");
    setColMode("hierarchical");
    setRowK(3);
    setColK(3);
    setKmeansSeed(1);
    setDistanceMetric("euclidean");
    setLinkageMethod("average");
    setParseError(null);
    setInjectionWarning(null);
    updVis({ _reset: true });
    updCellBorder({ _reset: true });
  };

  const nRows = rawMatrix.rowLabels.length;
  const nCols = rawMatrix.colLabels.length;
  const oversize = nRows > 500 || nCols > 500;

  // Accessible data-table model: the raw matrix in current display order, so
  // keyboard / screen-reader users get the same values the (image-rendered)
  // cells show. Truncated to a cell budget on huge matrices (see
  // TABLE_MAX_CELLS); the `note` tells the user when that happens.
  const tableModel = useMemo(() => {
    const maxRows = nCols > 0 ? Math.max(1, Math.floor(TABLE_MAX_CELLS / nCols)) : nRows;
    const shownRows = Math.min(nRows, maxRows);
    const fmt = (v: number): string =>
      Number.isFinite(v) ? String(Math.round(v * 1e4) / 1e4) : "";
    const rows: ChartDataTableRow[] = [];
    for (let ri = 0; ri < shownRows; ri++) {
      const origRi = rowOrder[ri];
      if (origRi == null) continue;
      const cells: string[] = [];
      for (let ci = 0; ci < nCols; ci++) {
        const origCi = colOrder[ci];
        cells.push(origCi == null ? "" : fmt(rawMatrix.matrix[origRi][origCi]));
      }
      rows.push({ header: rawMatrix.rowLabels[origRi], cells });
    }
    const columnHeaders = [vis.rowAxisLabel || tr("heatmap.table.rowHeader")].concat(
      colOrder.map((origCi) => rawMatrix.colLabels[origCi])
    );
    return { rows, columnHeaders, truncated: shownRows < nRows, shownRows };
  }, [rawMatrix, rowOrder, colOrder, nRows, nCols, vis.rowAxisLabel, tr]);
  // Clustering was requested on an axis with more observations than the
  // active mode's cap (see clusterCapFor) — it silently fell back to file
  // order, so tell the user why, naming the limit that applied.
  // Methods paragraph: normalisation, the clustering that actually ran
  // (null clusters = skipped, e.g. over the size cap), and the colour range.
  const methodsText = (): string => {
    const out: string[] = [];
    const nC = rawMatrix.colLabels.length;
    out.push(tr("heatmap.methods.size", { r: rawMatrix.rowLabels.length, c: nC }));
    if (normalization !== "none") out.push(tr(`heatmap.methods.${normalization}`));
    const rowH = rowCluster && rowCluster.mode === "hierarchical";
    const colH = colCluster && colCluster.mode === "hierarchical";
    const calls: string[] = [];
    if (rowH || colH) {
      // A legacy "ward" value runs as average linkage (UPGMA) in hclust.
      const link = linkageMethod === "ward" ? "average" : linkageMethod;
      const vars = {
        linkage: tr(`heatmap.methods.link.${link}`),
        distance: tr(`heatmap.methods.dist.${distanceMetric}`),
      };
      out.push(
        tr(
          rowH && colH
            ? "heatmap.methods.hierBoth"
            : rowH
              ? "heatmap.methods.hierRows"
              : "heatmap.methods.hierCols",
          vars
        )
      );
      const anyMissing = normalized.some((r) => r.some((v) => !Number.isFinite(v)));
      if (anyMissing && distanceMetric !== "correlation") out.push(tr("heatmap.methods.missing"));
      const d = (x: string): string =>
        distanceMetric === "correlation"
          ? `as.dist(1 - cor(t(${x}), use = "pairwise.complete.obs"))`
          : `dist(${x}, method = "${distanceMetric}")`;
      if (rowH) calls.push(`hclust(${d("x")}, method = "${link}")`);
      if (colH) calls.push(`hclust(${d("t(x)")}, method = "${link}")`);
    }
    if (rowCluster && rowCluster.mode === "kmeans")
      out.push(tr("heatmap.methods.kmRows", { k: rowCluster.k, seed: kmeansSeed }));
    if (colCluster && colCluster.mode === "kmeans")
      out.push(tr("heatmap.methods.kmCols", { k: colCluster.k, seed: kmeansSeed }));
    out.push(
      tr("heatmap.methods.colour", {
        lo: Number(vis.vmin).toLocaleString(getLang()),
        hi: Number(vis.vmax).toLocaleString(getLang()),
        palette: vis.palette,
      })
    );
    out.push(softwareSentence(calls));
    return out.join(" ");
  };

  const rowClusterCapped = nRows > clusterCapFor(rowMode);
  const colClusterCapped = nCols > clusterCapFor(colMode);
  const clusterCapped = rowClusterCapped || colClusterCapped;
  const clusterCapMax = rowClusterCapped
    ? clusterCapFor(rowMode)
    : colClusterCapped
      ? clusterCapFor(colMode)
      : 0;

  return (
    <PlotToolShell
      state={shell}
      toolName="heatmap"
      title="Heatmap"
      visInit={VIS_INIT_HEATMAP}
      steps={["upload", "configure", "plot"]}
      stepLabels={{ configure: tr("heatmap.step.importCheck") }}
      canNavigate={canNavigate}
    >
      {step === "upload" && (
        <UploadStep
          sepOverride={sepOverride}
          setSepOverride={setSepOverride}
          handleFileLoad={handleFileLoad}
          handleTextPaste={handleTextPaste}
          onLoadExample={loadExample}
        />
      )}

      {step === "configure" && nRows > 0 && (
        <div>
          <p
            style={{
              margin: "0 0 10px",
              fontSize: 12,
              color: "var(--text-muted)",
            }}
          >
            <strong>{fileName || tr("heatmap.cfg.pastedData")}</strong>
            {tr("heatmap.cfg.parsed", { rows: nRows, cols: nCols })}
            <DetectedSeparatorBadge sep={detectedSep} />
            {warnings.nonNumeric > 0 && (
              <>
                {" "}
                ·{" "}
                <span style={{ color: "var(--warning-text)" }}>
                  {tr("heatmap.cfg.nonNumeric", {
                    n: warnings.nonNumeric,
                    count: warnings.nonNumeric,
                  })}
                </span>
              </>
            )}
            {oversize && !clusterCapped && (
              <>
                {" "}
                · <span style={{ color: "var(--warning-text)" }}>{tr("heatmap.cfg.large")}</span>
              </>
            )}
            {clusterCapped && (
              <>
                {" "}
                ·{" "}
                <span style={{ color: "var(--warning-text)" }}>
                  {tr("heatmap.cfg.clusterCapped", { max: clusterCapMax })}
                </span>
              </>
            )}
          </p>
          <DataPreview
            headers={[""].concat(rawMatrix.colLabels)}
            rows={rawMatrix.matrix.map((row, ri) =>
              [rawMatrix.rowLabels[ri]].concat(
                row.map((v) => (Number.isFinite(v) ? String(v) : ""))
              )
            )}
          />
        </div>
      )}

      {step === "plot" && nRows > 0 && (
        <div>
          <div style={{ display: "flex", gap: 20, alignItems: "flex-start" }}>
            <PlotControls
              vis={vis}
              updVis={updVis}
              cellBorder={cellBorder}
              updCellBorder={updCellBorder}
              matrixRef={matrixRef}
              chartRef={chartRef}
              rawMatrix={rawMatrix}
              resetAll={resetAll}
              fileName={fileName}
              normalization={normalization}
              setNormalization={setNormalization}
              rowMode={rowMode}
              setRowMode={setRowMode}
              colMode={colMode}
              setColMode={setColMode}
              rowK={rowK}
              setRowK={setRowK}
              colK={colK}
              setColK={setColK}
              kmeansSeed={kmeansSeed}
              setKmeansSeed={setKmeansSeed}
              distanceMetric={distanceMetric}
              setDistanceMetric={setDistanceMetric}
              linkageMethod={linkageMethod}
              setLinkageMethod={setLinkageMethod}
              skew={skew}
              presets={presets}
              sortedValues={sortedValues}
              rangeIsDiverging={rangeIsDiverging}
              setRange={setRange}
            />

            <div
              style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column", gap: 12 }}
            >
              {skew && <SkewAlert skew={skew} onApply={applyRobustRange} />}
              <div
                style={{
                  display: "flex",
                  gap: 12,
                  alignItems: "flex-start",
                  flexWrap: "wrap",
                }}
              >
                <div
                  className="dv-panel dv-plot-card"
                  style={{
                    padding: 20,
                    background: "var(--plot-card-bg)",
                    borderColor: "var(--plot-card-border)",
                    display: "flex",
                    flexDirection: "column",
                    gap: 12,
                    alignItems: "center",
                    flex: 1,
                    minWidth: 0,
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                      alignSelf: "stretch",
                      gap: 12,
                      flexWrap: "wrap",
                    }}
                  >
                    <div
                      style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}
                    >
                      {hasSelection ? (
                        <button
                          onClick={clearSelection}
                          className="dv-btn dv-btn-secondary"
                          style={{ padding: "4px 10px", fontSize: 11 }}
                        >
                          {tr("heatmap.plot.clear")}
                        </button>
                      ) : (
                        <span
                          style={{
                            fontSize: 11,
                            color: "var(--text-muted)",
                            fontStyle: "italic",
                          }}
                        >
                          {tr("heatmap.plot.dragHint")}
                        </span>
                      )}
                    </div>
                    <div style={{ marginLeft: "auto" }}>
                      <MethodsButton getText={methodsText} />
                    </div>
                  </div>
                  <HeatmapChart
                    ref={chartRef}
                    rowLabels={rawMatrix.rowLabels}
                    colLabels={rawMatrix.colLabels}
                    matrix={normalized}
                    rawMatrix={rawMatrix.matrix}
                    rowOrder={rowOrder}
                    colOrder={colOrder}
                    rowCluster={rowCluster}
                    colCluster={colCluster}
                    vmin={vis.vmin}
                    vmax={vis.vmax}
                    showLegendHistogram={vis.showLegendHistogram}
                    palette={vis.palette}
                    invertPalette={vis.invertPalette}
                    cellBorder={cellBorder}
                    plotTitle={vis.plotTitle}
                    plotSubtitle={vis.plotSubtitle}
                    rowAxisLabel={vis.rowAxisLabel}
                    colAxisLabel={vis.colAxisLabel}
                    showRowLabels={vis.showRowLabels}
                    showColLabels={vis.showColLabels}
                    showRowDendrogram={vis.showRowDendrogram}
                    showColDendrogram={vis.showColDendrogram}
                    interactive={true}
                    selection={selection}
                    onBrushEnd={onBrushEnd}
                    onAxisSelect={selectAxis}
                    onClearSelection={clearSelection}
                  />
                </div>

                {hasSelection && (
                  <DetailView
                    rawMatrix={rawMatrix}
                    normalized={normalized}
                    detailRowOrder={detailRowOrder}
                    detailColOrder={detailColOrder}
                    mainRowCluster={rowCluster}
                    mainColCluster={colCluster}
                    vis={vis}
                    cellBorder={cellBorder}
                    detailChartRef={detailChartRef}
                    fileName={fileName}
                    clusterId={selection.clusterId}
                  />
                )}
              </div>
              {hasSelection && (
                <DetailPreviewCard
                  rawMatrix={rawMatrix}
                  normalized={normalized}
                  detailRowOrder={detailRowOrder}
                  detailColOrder={detailColOrder}
                  fileName={fileName}
                  clusterId={selection.clusterId}
                />
              )}
              <ChartDataTable
                summaryLabel={tr("heatmap.table.summary")}
                caption={tr("heatmap.table.caption", { rows: nRows, cols: nCols })}
                columnHeaders={tableModel.columnHeaders}
                rows={tableModel.rows}
                note={
                  tableModel.truncated
                    ? tr("heatmap.table.truncated", { shown: tableModel.shownRows, total: nRows })
                    : null
                }
              />
            </div>
          </div>
        </div>
      )}
    </PlotToolShell>
  );
}
